  /* Semantic - 다크 위 어두운 틴트 bg + 밝고 또렷한 fg */
  --color-success-bg: #172E12;
  --color-success-fg: #7FCB6F;
  --color-warning-bg: #2E2410;
  --color-warning-fg: #FFC24D;
  --color-error-bg:   #2E1512;
  --color-error-fg:   #E58474;
  --color-info-bg:    #16282F;
  --color-info-fg:    #6FC0EE;

  /* Surface (배경 위계) */
  --bg-base:     #0E1A12;   /* 밤 목장 잉크 그린 캔버스 */
  --bg-subtle:   #14231A;   /* 섹션 */
  --bg-elevated: #16241A;   /* 카드 */
  --bg-overlay:  rgba(0,0,0,0.66);

  /* Text 위계 */
  --text-primary:    #F2F7EE;   /* 크림 잉크 */
  --text-secondary:  #C4D2C0;
  --text-tertiary:   #9DB0A0;
  --text-on-primary: #0E1A12;   /* 초록/옐로 위 */
  --text-disabled:   #5C6E5C;

  /* Border */
  --border-default: #2C4030;
  --border-subtle:  #1D2E22;
  --border-strong:  #F2F7EE;   /* 손그림 아웃라인(다크 위 크림 잉크) */
  --border-focus:   #7FCB6F;
}

[data-theme="light"] {
  /* Primary - Pasture Green (초원) */
  --color-primary-50:  #EAF7E7;
  --color-primary-100: #CDEBC5;
  --color-primary-200: #A6DB9A;
  --color-primary-300: #7FCB6F;
  --color-primary-400: #63B851;
  --color-primary-500: #4C9F45;   /* Ben & Jerry's Pasture Green */
  --color-primary-600: #3D8438;
  --color-primary-700: #2F6A2C;
  --color-primary-800: #234F21;
  --color-primary-900: #163415;

  /* Secondary - Naples Yellow (캐러멜·와플 옐로, Pantone 130C 근사) */
  --color-secondary-50:  #FFF4DA;
  --color-secondary-300: #FFCE6B;
  --color-secondary-500: #FFAD14;   /* 공식 옐로 */
  --color-secondary-700: #C67F00;

  /* Tertiary - Sky Blue (구름 하늘) */
  --color-sky-100: #DDF1FB;
  --color-sky-300: #8FD3F4;
  --color-sky-500: #4FB0E6;   /* (추정) 하늘 블루 */
  --color-sky-700: #2A7FB5;

  /* Accent - Cow Pink (젖소 코·혀) */
  --color-pink-400: #F2A9C0;   /* (추정) */

  /* Neutral - Warm off-white / cocoa ink */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #FBFAF4;   /* 바닐라 오프화이트 */
  --color-neutral-100:  #F3F0E4;
  --color-neutral-200:  #E4DFCF;   /* border */
  --color-neutral-300:  #CFC9B6;
  --color-neutral-500:  #9C9484;
  --color-neutral-700:  #5B5346;   /* text secondary (코코아) */
  --color-neutral-800:  #35301F;
  --color-neutral-900:  #1F1B12;   /* text primary (초콜릿 잉크) */
  --color-neutral-1000: #000000;

  /* Semantic */
  --color-success-bg: #E7F4DE;
  --color-success-fg: #3D8438;
  --color-warning-bg: #FFF1D0;
  --color-warning-fg: #B57400;
  --color-error-bg:   #FBE0DE;
  --color-error-fg:   #C0392B;
  --color-info-bg:    #DDF1FB;
  --color-info-fg:    #2A7FB5;

  /* Surface (배경 위계) */
  --bg-base:     #EAF6FD;   /* 옅은 하늘 캔버스 */
  --bg-subtle:   #FBFAF4;   /* 바닐라 섹션 */
  --bg-elevated: #FFFFFF;   /* 카드 */
  --bg-overlay:  rgba(31,27,18,0.55);

  /* Text 위계 */
  --text-primary:    #1F1B12;   /* 초콜릿 잉크 */
  --text-secondary:  #5B5346;
  --text-tertiary:   #9C9484;
  --text-on-primary: #FFFFFF;   /* 초록/블루 위 */
  --text-disabled:   #CFC9B6;

  /* Border */
  --border-default: #E4DFCF;
  --border-subtle:  #F3F0E4;
  --border-strong:  #1F1B12;   /* 손그림 아웃라인(굵은 잉크) */
  --border-focus:   #4C9F45;
}




.btn {
  font: 800 15px/1 'Chunk', Georgia, serif;
  border: 2.5px solid var(--border-strong);
  border-radius: var(--radius-full);
  padding: 12px 22px;
  display: inline-flex; align-items: center; gap: 8px;
  cursor: pointer;
  transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease;
}
.btn-primary { background: var(--color-primary-500); color: var(--text-on-primary); box-shadow: var(--shadow-ink); }
.btn-primary:hover  { transform: translate(-1px,-1px); box-shadow: 4px 4px 0 #F2F7EE; }
.btn-primary:active { transform: translate(2px,2px);  box-shadow: 1px 1px 0 #F2F7EE; }
.btn-primary:disabled { background: var(--color-neutral-300); border-color: var(--color-neutral-300); color: var(--text-disabled); box-shadow: none; cursor: not-allowed; }
.btn-secondary { background: var(--color-secondary-500); color: var(--text-on-primary); box-shadow: var(--shadow-ink); }
.btn-ghost   { background: transparent; color: var(--text-primary); border-color: var(--border-strong); box-shadow: none; }
.btn-danger  { background: var(--color-error-fg); color: var(--text-on-primary); box-shadow: var(--shadow-ink); }
.btn-loading { color: transparent; position: relative; }
.input {
  font: 500 15px/1.4 'Filson', Inter, sans-serif;
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 2.5px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: 12px 16px;
}
.input::placeholder { color: var(--text-tertiary); }
.input:focus  { outline: none; border-color: var(--border-focus); box-shadow: 0 0 0 3px rgba(127,203,111,0.30); }
.input.error  { border-color: var(--color-error-fg); box-shadow: 0 0 0 3px rgba(229,132,116,0.25); }
.input:disabled { background: var(--bg-subtle); color: var(--text-disabled); border-color: var(--border-default); }
.card {
  background: var(--bg-elevated);
  border: 2.5px solid var(--border-strong);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-ink);
}
.card-emphasis { background: var(--color-sky-100); }
.card-outlined { box-shadow: none; border: 2px solid var(--border-default); }
.pint {                 /* 파인트 통 시그니처 카드 */
  border-radius: 20px 20px 24px 24px;
  overflow: hidden;
  border: 2.5px solid var(--border-strong);
  background: linear-gradient(#1B3A4A, #0E1A12);
}
.tag {
  font: 800 12px/1 'Chunk', Georgia, serif;
  text-transform: uppercase; letter-spacing: 0.02em;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  border: 2px solid var(--border-strong);
  display: inline-flex; align-items: center; gap: 4px;
}
.tag-solid   { background: var(--color-secondary-500); color: var(--text-on-primary); }
.tag-subtle  { background: var(--color-primary-50); color: var(--color-primary-700); border-color: var(--color-primary-300); }
.tag-outline { background: transparent; color: var(--text-primary); }
.nav {
  background: var(--color-primary-500);
  border-bottom: 3px solid var(--border-strong);
  padding: 12px 48px;
  display: flex; align-items: center; gap: 24px;
}
.nav .brand { font: 800 24px/1 'Chunk', Georgia, serif; color: var(--text-on-primary); letter-spacing: -0.5px; }
.nav a { font: 700 14px/1 'Filson', Inter, sans-serif; color: var(--text-on-primary); text-decoration: none; }
.nav a:hover { color: var(--color-neutral-50); }
.nav .cta { margin-left: auto; }
